import {tendencyScenarios} from './tendency-scenarios.js';
const histories={
 flop:[['Preflop','BTN opens to 2.5bb. SB folds. You call in the BB.'],['Flop','You check. BTN bets 2bb into 5.5bb.']],
 turn:[['Preflop','BTN opens to 2.5bb. SB folds. You call in the BB.'],['Flop','You check. BTN bets 2bb. You call.'],['Turn','You check. BTN bets 5bb into 9.5bb.']],
 river:[['Preflop','BTN opens to 2.5bb. SB folds. You call in the BB.'],['Flop','You check. BTN bets 2bb. You call.'],['Turn','You check. BTN bets 5bb. You call.'],['River','You check. BTN bets 12bb into 19.5bb.']],
 preflop:[['Preflop','BTN opens to 2.5bb. SB folds. Action is on you in the BB.']]
};
const make=(id,title,topic,level,street,hero,board,range,question,hint,lesson,extra={})=>({id,title,topic,level,street,hero:hero.split(' '),board:board?board.split(' '):[],range:range.split(' '),question,hint,lesson,history:histories[street],kind:'remaining',...extra});
export const scenarios=[
make('top-pair','One ace changes everything','counting','Foundations','flop','As Qc','Ah 7d 2c','AK','How many AK combos remain?','Count the available aces, then multiply by the available kings. AK includes suited and offsuit hands.','There are four of each rank in the deck. Remove the board ace and your ace before multiplying. Your queen does not remove any AK combinations.'),
make('pocket-pairs','Six becomes three','counting','Foundations','preflop','Qs 9h','','QQ','How many QQ combos remain?','A pocket pair is a choice of two cards from the available cards of that rank: n × (n − 1) ÷ 2.','One queen in your hand leaves three queens. Choose any two: 3 × 2 ÷ 2 = 3. Order does not create a new combo.'),
make('suited','Follow the suits','counting','Foundations','flop','As Qc','Ah 7d 2c','AKs','How many AKs combos remain?','A suited hand has one combo per suit. Cross out a suit if either required card is visible.','Suited combinations need both ranks in the same suit. An exposed ace rules out its entire suited AK combination; unrelated ranks do not.'),
make('offsuit','Keep the suits apart','counting','Foundations','flop','As Qc','Ah 7d 2c','AKo','How many AKo combos remain?','Count all AK, then subtract the suited combinations still available.','Offsuit does not mean twelve forever. Start with the remaining rank combinations, then exclude the surviving same-suit combinations.'),
make('sets','Three possible sets','counting','Applied','flop','As Qc','Ah 7d 2c','AA 77 22','How many set combos remain?','Count AA, 77, and 22 separately. Remember that your ace also removes AA combinations.','Each board rank leaves three cards of that rank, normally making three set combinations. Your matching hole card further reduces the top set to one combo.'),
make('two-pair','Both ranks are visible','counting','Applied','flop','As Qc','Ah Kd 2c','AK','How many AK combos remain?','Remove visible aces and kings independently, then multiply.','Two visible aces and one visible king leave two aces and three kings. Both the board and your own hand are dead cards for villain.'),
make('pocket-street','A turn card removes a pair','counting','Applied','turn','As Qc','Jh 7d 2c Jd','JJ 77 22','How many listed pocket-pair combos remain?','There are only two jacks left after the turn. Count each pocket pair independently.','On a paired board, do not assume every pocket pair makes a set. JJ is quads here; 77 and 22 are full houses. The combination formula stays the same.'),
make('range-union','Put the pieces together','counting','Applied','turn','As Qc','Ah 7d 2c 9h','AA AKs AKo AQs','How many combos remain in this range?','Count each hand class separately, then add them. AKs and AKo do not overlap.','A range is a collection of distinct two-card combinations. Add disjoint hand classes; never count the same physical hand twice.'),
make('ace-blocker','Measure your blocker','blockers','Foundations','flop','As Qc','Ah 7d 2c','AK','How many AK combos does your hand block?','First count using only the board. Then count using the board plus your hand. Subtract.','A blocker count is relative to the same board with your hole cards ignored. One available ace pairs with every available king, so holding that ace removes four AK combos.',{kind:'blocked'}),
make('king-blocker','One card, several hands','blockers','Applied','flop','Ks Qc','Ah 7d 2c','AK KQs','How many listed combos does your hand block?','Find every board-legal combination containing either of your cards. A combo hit twice is still only one combo.','Count the union of removed combinations. Your king affects both AK and KQs; your queen can remove another suited KQ combo.',{kind:'blocked'}),
make('nut-flush','The nut-flush blocker','blockers','Applied','river','As Qd','Ks 9s 2s 7h 3c','AsQs AsJs AsTs As8s As6s As5s As4s','How many listed nut-flush combos remain?','Every listed hand needs the same ace. Is that card available to villain?','Holding the ace of the flush suit removes every listed ace-high flush. It does not remove all flushes, and by itself it does not prove a bluff is profitable.'),
make('flush-removal','Blocking some flushes','blockers','Advanced','river','Qs Jh','Ks 9s 2s 7h 3c','AsQs AsJs AsTs QsJs QsTs JsTs 8s6s','How many listed flush combos does your hand block?','These are exact two-card hands. Cross out each that contains one of your hole cards.','A queen of the flush suit removes only flushes containing that exact queen. Your jack of another suit does not block suited spade hands.',{kind:'blocked'}),
make('missed-draw','Let the missed draws survive','unblockers','Applied','river','Ac Qd','Ah 9h 5c 2d 7s','KhQh KhJh KhTh QhJh QhTh JhTh','How many listed missed-draw bluffs remain?','These are exact heart-heart combinations. Do either of your cards appear in any of them?','An unblocker leaves relevant combinations available. Here your hand leaves all of the specified missed heart draws intact. More available bluffs can help a bluff-catcher, but betting frequencies still matter.',{alternative:['Ac','Qh'],comparison:'Replacing your queen with the queen of hearts would remove three of these bluffs.'}),
make('block-bluffs','A blocker you might not want','unblockers','Applied','river','Ac Qh','Ah 9h 5c 2d 7s','KhQh KhJh KhTh QhJh QhTh JhTh','How many listed missed-draw bluffs remain?','The queen of hearts appears in three of the listed bluff candidates.','Blocking bluffs can be undesirable when bluff-catching. Relative to the same hand with the queen of diamonds, this hand leaves fewer of the specified missed draws available.',{alternative:['Ac','Qd'],comparison:'Replacing your queen with the queen of diamonds would leave three additional bluffs available.'}),
make('straight-blocker','Remove the made straights','blockers','Advanced','river','Ts Tc','Qs Jd 9c 2h 3s','KT T8','How many listed straight combos remain?','Both of your tens are dead. Each surviving ten can pair with four kings or four eights.','Holding two tens cuts each of the listed rank combinations in half. Blocking value is one useful input; a decision still needs the rest of the range and the price.'),
make('unblock-straights','Leave the missed straight draws','unblockers','Advanced','river','As Qc','Ah Jd 7c 3s 2h','KQ KT QT','How many listed missed straight-draw candidates remain?','Your queen removes KQ and QT combinations, but your ace does not touch this range.','The selected range contains missed gutshot candidates. A queen blocks some of them; a low card of an unrelated rank would leave more available. These are assumed bluff candidates, not guaranteed river bluffs.',{alternative:['As','6c'],comparison:'With an unrelated six instead of the queen, eight additional candidates would be available.'}),
make('turn-flushdraw','Draws need the right two cards','counting','Advanced','turn','Qh Jc','Ah 9h 5c 2d','KhQh KhJh KhTh QhJh QhTh JhTh 8h7h','How many listed flush-draw combos remain?','The listed hands are exact combinations, not all suited hands. Remove only exact card collisions.','With two hearts on the board, these heart-heart hands have a flush draw. Your queen of hearts removes three listed combinations; your club jack does not block a heart jack.'),
make('full-house','On a paired river','counting','Advanced','river','As Qc','Ah Ad 7c 2d 9h','AA 77 22 99 AK','How many listed value combos remain?','Only one ace is unaccounted for. AA needs two; AK needs only one. Count each class.','AA is impossible with three aces visible. Each board-matching pocket pair has three combinations, and AK has four. This is a selected value range, not every possible value hand.')
];
export const topics={all:'All concepts',tendencies:'Reading ranges',counting:'Combo counting',blockers:'Blockers',unblockers:'Unblockers'};

// Position variations preserve the same explicit card-removal problems.
for (const scenario of scenarios) {
  scenario.heroPosition = 'BB';
  scenario.villainPosition = 'BTN';
  scenario.potAfterBet = {preflop:4,flop:7.5,turn:14.5,river:31.5}[scenario.street];
  if (['two-pair','pocket-street','straight-blocker'].includes(scenario.id)) {
    scenario.villainPosition = scenario.id === 'pocket-street' ? 'HJ' : 'CO';
    scenario.history = scenario.history.map(([street,line],i) => [street, i === 0 ? `${scenario.villainPosition} opens to 2.5bb. Everyone folds to you in the BB. You call.` : line.replaceAll('BTN',scenario.villainPosition)]);
  }
  if (['sets','flush-removal','turn-flushdraw'].includes(scenario.id)) {
    scenario.heroPosition='BTN'; scenario.villainPosition='CO';
    scenario.potAfterBet={flop:8.5,turn:15.5,river:32.5}[scenario.street];
    scenario.history=[['Preflop','CO opens to 2.5bb. You call on the BTN. Both blinds fold.'],['Flop','CO bets 2bb into 6.5bb.'+(scenario.street==='flop'?'':' You call.')]];
    if(['turn','river'].includes(scenario.street))scenario.history.push(['Turn','CO bets 5bb into 10.5bb.'+(scenario.street==='turn'?'':' You call.')]);
    if(scenario.street==='river')scenario.history.push(['River','CO bets 12bb into 20.5bb.']);
  }
}

scenarios.push(...tendencyScenarios);
